-        this.source = Objects.requireNonNull(source);
-        this.secretKey = Objects.requireNonNull(secretKey);
-        if (packetLength <= 0 || packetLength >= EncryptedRepository.MAX_PACKET_LENGTH_IN_BYTES) {
